      "name": "Beneficiaries",
      "description": "Operations on Beneficiaries"
    }
  ],
  "paths": {
    "/customers/{customerId}/beneficiaries": {
      "post": {
        "tags": [
          "Beneficiaries"
        ],
        "summary": "Create a new beneficiary for a specified customer",
        "description": "The ability to create a new beneficiary for a customer, using their customer ID as a reference.",
        "operationId": "createBeneficiary",
        "parameters": [
          {
            "name": "customerId",
            "in": "path",
            "description": "ID of customer to create beneficiary for",
            "required": true,
            "style": "simple",
            "explode": false,
            "schema": {
              "type": "string"
            }
          }
        ],
        "requestBody": {
          "content": {
            "application/json": {
              "schema": {
                "$ref": "#/components/schemas/account.CreateBeneficiaryRequest"
              }
            }
          },
          "required": true
        },
        "responses": {
          "201": {
            "description": "Created",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/account.BeneficiaryResponse"
                }
              }
            }
          },
          "400": {
            "description": "Validation errors",
            "content": {
              "*/*": {
                "schema": {
                  "type": "array",
                  "items": {
                    "$ref": "#/components/schemas/account.MessageResponse"
                  }
                }
              }
            }
          }
        },
        "security": [
          {
            "HMAC": []
          },
          {
            "TOKEN": []
          }
        ]
      }
    }
  },
  "components": {
    "schemas": {
      "account.IdentifierResponse": {
        "type": "object",
        "description": "Account Identifier",
        "properties": {
          "type": {
            "type": "string"
          },
          "accountNumber": {
            "type": "string",
            "description": "Bank account Sort Code",
            "example": "12345678"
          },
          "accountType": {
            "type": "string",
            "description": "Bank account type like PERSONAL/BUSINESS",
            "enum": [
              "PERSONAL",
              "BUSINESS"
            ]
          },
          "sortCode": {
            "type": "string",
            "description": "Bank account Sort Code",
            "example": "000000"
          },
          "iban": {
            "type": "string",
            "example": "GB20MODR04001401100000"
          },
          "bic": {
            "type": "string",
            "example": "MODRGB21"
          },
          "currency": {
            "type": "string",
            "example": "GBP"
          },
          "countrySpecificDetails": {
            "$ref": "#/components/schemas/account.IdentifierCountrySpecificDetailsResponse",
            "example": {
              "branchCode": "123456789"
            }
          },
          "productId": {
            "type": "string",
            "example": "O2100001"
          }
        }
      },
      "account.BeneficiaryResponse": {
        "type": "object",
        "description": "Beneficiary",
        "properties": {
          "id": {
            "type": "string",
            "description": "Unique reference for the Beneficiary.",
            "example": "B00000001A"
          },
          "name": {
            "type": "string",
            "description": "Name for the Beneficiary"
          },
          "birthdate": {
            "type": "string",
            "format": "date",
            "description": "Date of birth for the Beneficiary in yyyy-MM-dd format"
          },
          "emailAddress": {
            "type": "string",
            "description": "Email address for the Beneficiary"
          },
          "phoneNumber": {
            "type": "string",
            "description": "Phone number for the Beneficiary in international pattern"
          },
          "destinationIdentifier": {
            "$ref": "#/components/schemas/account.IdentifierResponse"
          },
          "redirectedDestination": {
            "$ref": "#/components/schemas/account.IdentifierResponse",
            "description": "Provides new account details where the beneficiary's account details have been redirected by the scheme."
          },
          "defaultReference": {
            "type": "string",
            "description": "Default reference used for payments to the Beneficiary."
          },
          "status": {
            "type": "string",
            "description": "Status of the Beneficiary. Can be:"
          },
          "created": {
            "type": "string",
            "format": "date-time",
            "description": "Datetime the Beneficiary was created.Format is 'yyyy-MM-dd'T'HH:mm:ssZ' where Z is UTC offset. e.g 2017-01-28T01:01:01+0000",
            "example": "2017-01-28T01:01:01+0000"
          },
          "accountId": {
            "type": "string",
            "description": "Id of the account if this beneficiary is a Modulr account, null otherwise"
          },
          "externalReference": {
            "type": "string",
            "description": "External system reference for the Beneficiary"
          },
          "approvalRequired": {
            "type": "boolean",
            "description": "Indicates if the beneficiary creation is pending approval"
          },
          "customerId": {
            "type": "string",
            "description": "Id of the customer than owns this beneficiary",
            "example": "C0000001"
          },
          "updated": {
            "type": "string",
            "format": "date-time",
            "description": "Datetime the Beneficiary was last updated.Format is 'yyyy-MM-dd'T'HH:mm:ssZ' where Z is UTC offset. e.g 2017-01-28T01:01:01+0000",
            "example": "2017-01-28T01:01:01+0000"
          },
          "address": {
            "$ref": "#/components/schemas/account.AddressResponse",
            "description": "address of the beneficiary"
          },
          "qualifier": {
            "type": "string",
            "description": "Qualifier for this beneficiary"
          },
          "approvalRequestId": {
            "type": "string",
            "description": "Approval request ID for pending records."
          },
          "approvalStatus": {
            "type": "string",
            "description": "Approval status of item.",
            "enum": [
              "NOTNEEDED",
              "PENDING",
              "APPROVED",
              "REJECTED",
              "DELETED"
            ]
          },
          "accessGroups": {
            "type": "array",
            "description": "Access groups associated with beneficiary.",
            "items": {
              "type": "string"
            },
            "uniqueItems": true
          },
          "createdBy": {
            "type": "string",
            "description": "System or person who created the beneficiary"
          }
        }
      },
      "account.AddressRequest": {
        "type": "object",
        "properties": {
          "addressLine1": {
            "type": "string",
            "maxLength": 50,
            "minLength": 0
          },
          "addressLine2": {
            "type": "string",
            "maxLength": 50,
            "minLength": 0
          },
          "postTown": {
            "type": "string",
            "maxLength": 50,
            "minLength": 0
          },
          "postCode": {
            "type": "string",
            "maxLength": 10
          },
          "country": {
            "type": "string",
            "description": "Mandatory for international payments."
          },
          "countrySubDivision": {
            "type": "string",
            "maxLength": 35,
            "minLength": 0
          }
        }
      },
      "account.MessageResponse": {
        "type": "object",
        "properties": {
          "field": {
            "type": "string"
          },
          "code": {
            "type": "string",
            "enum": [
              "GENERAL",
              "BUSINESSRULE",
              "MFASTATUS",
              "MFAERROR",
              "MFATIMEOUT",
