          "bic": {
            "type": "string",
            "example": "MODRGB21",
            "pattern": "([a-zA-Z]{6,6}[a-zA-Z2-9][a-nA-Np-zP-Z0-9]([a-zA-Z0-9]{3})?)"
          },
          "currency": {
            "type": "string",
            "example": "GBP",
            "pattern": "[a-zA-Z]{3}"
          },
          "countrySpecificDetails": {
